// Package a holds Go suppression markers; every marked line must be reported.
package a

var s = "//nolint" // a marker inside a string literal passes

//nolint:errcheck // want
func f() {}

// nolint // want
func g() {}

// NOLINT:gosec want
func h() {}

//lint:ignore SA1000 reason want
func i() {}

//lint:file-ignore SA1000 reason want
func j() {}

//exhaustive:ignore want
func k() {}

// #nosec G101 want
func l() {}

/* nolint */ // want
func m()     {}

// Prose that mentions nolint mid-comment passes.
func n() {}

// Every leading '/', space and tab is stripped first, as golangci-lint does. These are
// trailing comments, so gofmt keeps their text as it is:

var o = 1 ///nolint:errcheck // want

var p = 2 // //nolint:errcheck // want

var q = 3 // /nolint:gosec want

var r = 4 //	nolint:errcheck // want (a tab after the slashes)

var s2 = 5 /*nolint:errcheck*/ // want

var t = 6 /** nolint */ // want

var u = 7 //gosec:disable G304 -- want

// A generated-code line after the package clause is no marker:
//
// Code generated by hand. DO NOT EDIT.
func v() {}
